    pm.expect(languageCode, 'LanguageCode should not be null').to.not.be.null;

    // Optionally, check if they are non-empty strings
    pm.expect(country, 'Country should be a non-empty string').to.not.be.empty;
    pm.expect(languageCode, 'LanguageCode should be a non-empty string').to.not.be.empty;
});
//check any duplicates are present
pm.test("Check for duplicate article ", function ()  {
    // Get the response body as JSON
    var response = pm.response.json();

    var articles = {};
    var duplicates = [];

    // Loop through each article in the response
    response.Tiles.forEach(function (article) {
        var articleTitle = article.Title;

        // If the article title already exists in the object, mark it as a duplicate
        if (articles[articleTitle]) {
            duplicates.push(articleTitle);
        } else {
            articles[articleTitle] = true;
        }
    });

    // Check if duplicates were found
    if (duplicates.length > 0) {
        pm.expect(duplicates.length).to.be.greaterThan(0); // Fail the test if duplicates are found
        console.log('Duplicate article Titles:', duplicates);
    } else {
        console.log('No duplicates found');
        pm.expect(duplicates.length).to.be.equal(0);  // Pass the test if no duplicates
    }
});
